import React, { createContext, useContext, useState, useRef } from 'react';

interface AnimationContextType {
  registerAnimation: (id: string, startFn: () => Promise<void>) => void;
  startAnimation: (id: string) => Promise<void>;
  resetAnimations: () => void;
  isAnimating: boolean;
  parentId?: string;
}

// Create context with default values
const AnimationContext = createContext<AnimationContextType>({
  registerAnimation: () => {},
  startAnimation: () => Promise.resolve(),
  resetAnimations: () => {},
  isAnimating: false,
});

// Animation system that coordinates between parent and child animations
export const AnimationProvider: React.FC<{
  children: React.ReactNode;
  parentId?: string;
}> = ({ children, parentId }) => {
  const [isAnimating, setIsAnimating] = useState(false);
  const animationsRef = useRef<Record<string, () => Promise<void>>>({});

  // Register an animation with a unique ID
  const registerAnimation = (id: string, startFn: () => Promise<void>) => {
    animationsRef.current[id] = startFn;
  };

  // Start an animation by ID and return its promise
  const startAnimation = async (id: string) => {
    const startFn = animationsRef.current[id];
    if (startFn) {
      setIsAnimating(true);
      try {
        await startFn();
      } catch (error) {
        console.error(`Animation ${id} failed:`, error);
      } finally {
        setIsAnimating(false);
      }
    } else {
      console.warn(`No animation registered with id: ${id}`);
    }
  };

  // Reset all registered animations
  const resetAnimations = () => {
    animationsRef.current = {};
    setIsAnimating(false);
  };

  return (
    <AnimationContext.Provider
      value={{
        registerAnimation,
        startAnimation,
        resetAnimations,
        isAnimating,
        parentId,
      }}
    >
      {children}
    </AnimationContext.Provider>
  );
};

// Hook to use the animation context
export const useAnimation = () => {
  return useContext(AnimationContext);
};

// Hook to generate a unique ID for animations
export const useAnimationId = (prefix: string = 'anim') => {
  const idRef = useRef<string>(`${prefix}-${Math.random().toString(36).substring(2, 9)}`);
  return idRef.current;
};

export default AnimationContext;
